}.
(* [comment removed for export] *)
Definition mkbc0 (fk : list kentry) (fs : list sfact) : bctx :=
  BC fk (facts_of fk) fs (mk_ri (facts_of fk)).

Lemma lin_range_ext : forall r1 r2 c ts, (forall a, r1 a = r2 a) -> lin_range r1 c ts = lin_range r2 c ts.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S@0!2+_2+S+S!1+^J0%x;R+P1!2+_2+S+P!1+^A3!3,^F3#3#2!1#;#3!2'_K#;#5!2'_K#;#4-_2RN$p0;R!2+_2+S+S1#11$lo;R+S$hi;R+S-2RN$~R+21!2'_;,_<#;2!2,^S0!4,_:+S+S!2'_@#27!2'_@#18!2,^S0!4,_:+S+S!2'_@#28!2'_@#17!1,^Z0!1#<#4-^JRN$x;R!1+^J01;2$p;R0-_2RN$p;R!2+_2+S+S1#11$al;R+S$ah;R+S-^JRN$x;R!1+^J01!3'_J#?#>#62$p0;R09::!2'_K#:#5!2'_K#:#4!3,^F3!4,_:+S+P#4#3#2$r1;R2$r2;R2$c;R+S$ts;R4$H;R%a;R+P!3+11!1#5#1!1#4#1!5'_13$ts;R4!3+11!3'_J#6#4#1!3'_J#5#4#1!2,61!3'_J#4#3!1,^B3$a0;R3-_2RN$p;R!2+_2+S+P%l;R4%~R!3+11!3'_J#8#6#1!3'_J#7#6#1!3+11!3'_J#9#75!3'_J#8#75#11$z;R+S$e;R+P!2$k;R+S$a;R+P$rest;R4$IH;R!3+11!3'_J#;#9#1!3'_J#:#9#1vd!6'X16$o;R1!3+11-^JRN$x;R!1+^J01#12$p;R0-_2RN$p;R!2+_2+S+S1#11$al;R+S$ah;R+S-^JRN$x;R!1+^J01!3'_J#@#>#62$p0;R09::<!6'X1!3'_J#;#:#2$o;R1!3+11-^JRN$x;R!1+^J01;2$p;R0-_2RN$p;R!2+_2+S+S1#11$al;R+S$ah;R+S-^JRN$x;R!1+^J01#42$p0;R09::<!2,61-^JRN$x;R!1+^J0162$p;R0-_2RN$p;R!2+_2+S+S1#11$al;R+S$ah;R+S-^JRN$x;R!1+^J01!3'_J#>#=#52$p0;R0-_2RN$p0;R!2+_2+S+S1#11$lo;R+S$hi;R+S-2RN$~R+21!2'_;,_<#:2!2,^S0!4,_:+S+S!2'_@#2=!2'_@#1>!2,^S0!4,_:+S+S!2'_@#2>!2'_@#1=::!3'_J#<#:#2#1!1#<#3!1#8#3!3+11!3'_J#<#:?!3'_J#;#:?#2#1#2").
