Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S;0!1+^A+^K!1+^A+2!1'eG!1'hC#9!3'eH!1'hC#:#8#7!1,^B+2!1'eA#8!1,^H#2!1,^H#5!1'eA#:!1,T,_<!1,^H#6$bc;R+_L$kn;R0$segs;R!1+^A+d[$rb;R+P$rk;R+S$n;R+Y$sx;R+2$hints;R1$acc;R!1+^A+dNvd-^ARN$l;R!1+^A+2!3+1+d\-^ARN$hints;R!1+^A+2+d\#12-YRN$n;R+Y+d\#52!9'eF#:#82#7#6#5#4#1#2$n0;R+Y!9'eF#;#93#8#7#6#54#3$b;R+2$l;R!1+^A+2!9'eF#<#:!1'eG!1'hC#;#9#8#7#6#3#4!9'eF#:#8#9#7#6#5#4#1#2#22-YRN$n;R+Y!3+1+d\-YRN$n;R+Y+d\#12!9'eF#:#82#7#6#1#44#2$n0;R+Y!9'eF#;#93#8#7#2#54#3!9'eF#:#8#9#7#6#1#44#2#42!2,6+d\!9'eF#9#7#8#6#5,^G#34#1$n;R+Y!1$n;R+Y!6'X0-2RN$~R+2052!3'gF+^K!1'fQ!1'e8#7#:!3'gF+^K'gD#:$l;R0!3+1+d\!9'eF#<#:#1#9#86#64#4!9'eF#<#:#;#9#86#64#4&b;R5+2&L;R!2,6+2#1!3+1+2!1'eA#9#1!1-2RN$b;R+2%L;R!3+1+2!1'eA#;#1!3+1+d\!9'eF#?#=-2RN$~R+20#22!3'gF+^K!1'fQ!1'e8#;#>!3'gF+^K'gD#>#<#;7#94#7!9'eF#?#=#>#<#;7#94#7#22$L;R!3+1+28,4&L;R!2'fW#;#1!3+1+P#;9!6'X+P9$rb;R+P!3+1+d\!9'eF#@#>!3'gF+^K!1'fQ!1'e8#<#?#1#<:#:4#8!9'eF#@#>#?#1#<:#:4#8!7'hD#?#=#>#;#5#9#7#<#1$L;R!3+1+28,7!9'hE#>#<#=#;#:!1,^H#4#8#6#1#13!3'hF#:#8#7#1$b;R+2$l;R!1+^A+2!2$h;R+2$hs;R1!2,6+d\!9'eF#=#;#<#:#9#8#7!3,^F+2#2#1#5#2#1!3+1+d\!9'hG#9!1'hC#8#7#6#5#4#3#2#1!9'eF#9#7#8#6#5#4#3#2#1").
Qed.

(* [comment removed for export] *)
Definition know_lookupABI (bc : bctx) (kx : kix) (segs : list Segment) (kn : list kentry) (rb : expr) (rk : Z)
         (n : nat) (sx : bool) (hints : list bool) (acc : list sidecond) : lres :=
  match know_lookupA0I bc kx segs rb rk n sx hints acc with
  | LMiss acc' hints' =>
      match know_bytes_lit segs kn rb rk n with
      | Some bs => LHit (lit_of_bytes sx n bs) acc' hints'
      | None => LMiss acc' hints'
      end
  | r => r
  end.
Lemma know_lookupABI_eq : forall bc kn segs,
  know_lookupABI bc (mk_kix kn) segs kn = know_lookupAB bc segs kn.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S>0!1+^A+2!1+^A+dN%acc;R1+d\%hints;R02%sx;R+23%n;R+Y4!9'eF#9#7#8#6#5#4#3#2#1!1+^A+dN!1+^A+2!3,e1#3#2#1!1+^A+S!2,e4#2#1-^JRN$x;R!1+^J:+d\!5'e2#:#;#9#8#72$bs;R:!3,e1!3'e3#7#8#1#3#2;!1'hC#8$bc;R+_L$kn;R!1+^A+^K$segs;R!1+^A+d[!5'_\+P%rk;R+S5!4'hH#3!1'hC#2#1#2!3'hI#3#1#2$x;R+P!5'_\+S5!5'hH#4!1'hC#3#2#3#1!4'hI#4#2#3#1$x0;R+S!5'_\+Y4!6'hH#5!1'hC#4#3#4#2#1!5'hI#5#3#4#2#1$x1;R+Y!5'_\+23!7'hH#6!1'hC#5#4#5#3#2#1!6'hI#6#4#5#3#2#1$x2;R+2!5'_\02!8'hH#7!1'hC#6#5#6#4#3#2#1!7'hI#7#5#6#4#3#2#1$x3;R0!5'_\1+d\!9'hH#8!1'hC#7#6#7#5#4#3#2#1!8'hI#8#6#7#5#4#3#2#1$x4;R1vd!6'X+d\6$l;R+d\!3+1+d\-d\RN$x;R+d\+d\#13$v;R+P$scs;R7$hints0;R89$acc';R7$hints';R8<,e5-d\RN$x;R+d\+d\!9'eF#:#8#9#7#6#5#4#3#23$v;R+P$scs;R7$hints0;R89$acc';R7$hints';R8<,e5!2,6+d\-d\RN$x;R+d\+d\63$v;R+P$scs;R7$hints0;R89$acc';R7$hints';R8-^JRN$x;R!1+^J:+d\!5'e2#9#:#8#7#62$bs;R:!3,e1!3'e3#6#7#1#3#2;,e5!9'hG#9=#7#6#5#4#3#2#1!9'hJ#9#8#7#6#5#4#3#2#1!3+1+d\!:'hH#9=#7#8#6#5#4#3#2#1!9'hI#9#7#8#6#5#4#3#2#1").
Qed.
End FPX_53.

Local Close Scope Z_scope.
Section FPX_54. Context {fx : PropExec.FPState}.


Definition sym_readBI (segs : list Segment) (ss : sym_state) (bc : bctx) (kx : kix) (scr : scripts)
           (a : saddr) (n : nat) (sx' : bool)
  : option (expr * list sidecond * scripts * nat) :=
  match log_lookupB bc (s_log ss) (a_base a) (a_off a) n sx' (sc_hints scr) [] with
  | LStuck => None
  | LHit v scs hints =>
      Some (extKB bc v, flat_scB bc a n ++ scs, SCR (sc_dirs scr) (sc_reads scr) hints, s_next ss)
  | LMiss scs hints =>
      match know_lookupABI bc kx segs (s_know ss) (a_base a) (a_off a) n sx' hints scs with
      | LStuck => None
      | LHit v scs' hints' =>
          Some (extKB bc v, flat_scB bc a n ++ scs', SCR (sc_dirs scr) (sc_reads scr) hints', s_next ss)
      | LMiss scs' hints' =>
          (* [comment removed for export] *)
          let i := s_next ss in
          let rv := match sc_reads scr with [] => EVar i | e :: _ => e end in
          let reads' := match sc_reads scr with [] => [] | _ :: t => t end in
          Some (rv, flat_scB bc a n ++ SCReadBase a n sx' rv :: scs', SCR (sc_dirs scr) reads' hints', S i)
      end
  end.


Definition sym_stepBI (bc : bctx) (kx : kix) (segs : list Segment) (i : instr) (ss : sym_state) (scr : scripts) : stepres :=
  let g r := sr_get (s_regs ss) r in
  let p := s_pc ss in
  match i with
  | OpImm op rd rs imm => SOk (sset ss rd (mkAluKB bc op (g rs) (ELit (bv_signed imm))) (p + 4)) [] scr
  | ShiftImm op rd rs sh => SOk (sset ss rd (mkAluKB bc op (g rs) (ELit (bv_unsigned sh))) (p + 4)) [] scr
  | Op op rd rs1 rs2 => SOk (sset ss rd (mkAluKB bc op (g rs1) (g rs2)) (p + 4)) [] scr
  | OpImm32 rd rs imm => SOk (sset ss rd (mkAluwKB bc ALU_ADD (g rs) (ELit (bv_signed imm))) (p + 4)) [] scr
  | ShiftImm32 op rd rs sh => SOk (sset ss rd (mkAluw op (g rs) (ELit (bv_unsigned sh))) (p + 4)) [] scr
  | Op32 op rd rs1 rs2 => SOk (sset ss rd (mkAluwKB bc op (g rs1) (g rs2)) (p + 4)) [] scr
  | Mul op rd rs1 rs2 => SOk (sset ss rd (mkMdKB bc op (g rs1) (g rs2)) (p + 4)) [] scr
  | Mul32 op rd rs1 rs2 => SOk (sset ss rd (mkMdw op (g rs1) (g rs2)) (p + 4)) [] scr
  | Lui rd imm => SOk (sset ss rd (ELit (bv_unsigned (Z_to_bv 64 (Z.shiftl (bv_signed imm) 12)))) (p + 4)) [] scr
  | Auipc rd imm => SOk (sset ss rd (ELit (bv_unsigned (Z_to_bv 64 (Z.shiftl (bv_signed imm) 12 + p)))) (p + 4)) [] scr
  | Jal rd imm => SOk (sset ss rd (ELit (p + 4)) (bv_unsigned (Z_to_bv 64 (p + bv_signed imm)))) [] scr
  | Jalr rd rs1 imm =>
      match conc_exprB bc (g rs1) with
      | ELit z => SOk (sset ss rd (ELit (p + 4)) (Z.land (bv_wrap 64 z + bv_signed imm) (-2) mod 2^64)) [] scr
      | _ => SStop
      end
  | Branch c rs1 rs2 imm =>
      let tk := bv_unsigned (Z_to_bv 64 (p + bv_signed imm)) in
      let a := g rs1 in let b := g rs2 in
      match match decide_branchB bc c a b with
            | Some t => Some t
            | None => match decide_branchB bc c (conc_exprB bc a) (conc_exprB bc b) with
                      | Some t => Some t
                      | None => enum_branchB bc c a b
                      end
            end with
      | Some t => SOk (sjump ss (if t then tk else p + 4)) [] scr
      | None =>
          match sc_dirs scr with
          | [] => SStop
          | t :: dirs' =>
              SOk (sjump ss (if t then tk else p + 4)) [SCBr t c a b]
                  (SCR dirs' (sc_reads scr) (sc_hints scr))
          end
      end
  | Fence _ _ _ _ _ => SOk (sjump ss (p + 4)) [] scr
  | FenceI _ _ _ => SOk (sjump ss (p + 4)) [] scr
  | Load sz sx rd rs imm =>
      let n := msize_bytes sz in
      (* [comment removed for export] *)
      let sx' := match sz with SZ8 => false | _ => sx end in
      let a := to_saddrKB bc (g rs) (bv_signed imm) in
      match sym_readBI segs ss bc kx scr a n sx' with
      | None => SStop
      | Some (v, scs, scr', nx') =>
          SOk (SSR (p + 4) (if bv_eqb rd 0 then s_regs ss else sr_upd (s_regs ss) (ridx rd) v)
                   (s_log ss) (s_know ss) nx' (s_resv ss)) scs scr'
      end
  | Store sz rs1 rs2 imm =>
      let n := msize_bytes sz in
      let a := to_saddrKB bc (g rs1) (bv_signed imm) in
      match resv_inval (s_resv ss) a with
      | None => SStop
      | Some r' =>
          SOk (SSR (p + 4) (s_regs ss) (SE a n (g rs2) :: s_log ss) (s_know ss) (s_next ss) r')
              (flat_scB bc a n ++ storeok_scB bc a n) scr
      end
  (* [comment removed for export] *)
  | Lr wd _ _ rd rs =>
      let n := msize_bytes (amo_sz wd) in
      let e := g rs in
      if amo_alignedbB bc e wd then
        let a := to_saddrKB bc e 0 in
        match sym_readBI segs ss bc kx scr a n (amo_sx wd) with
        | None => SStop
        | Some (v, scs, scr', nx') =>
            SOk (SSR (p + 4) (if bv_eqb rd 0 then s_regs ss else sr_upd (s_regs ss) (ridx rd) v)
                     (s_log ss) (s_know ss) nx' (Some a)) scs scr'
        end
      else SStop
  | Sc wd _ _ rd rs1 rs2 =>
      let n := msize_bytes (amo_sz wd) in
      let e := g rs1 in
      if amo_alignedbB bc e wd then
        let a := to_saddrKB bc e 0 in
        match s_resv ss with
        | Some r =>
            if saddr_eqb r a then
              SOk (SSR (p + 4) (if bv_eqb rd 0 then s_regs ss else sr_upd (s_regs ss) (ridx rd) (ELit 0))
                       (SE a n (g rs2) :: s_log ss) (s_know ss) (s_next ss) None)
                  (flat_scB bc a n ++ storeok_scB bc a n) scr
            else SStop   (* [comment removed for export] *)
        | None => SStop
        end
      else SStop
  | Amo op wd _ _ rd rs1 rs2 =>
      match amo_aluop op with
      | None => SStop
      | Some aop =>
          let n := msize_bytes (amo_sz wd) in
          let e := g rs1 in
          if amo_alignedbB bc e wd then
            let a := to_saddrKB bc e 0 in
            match resv_inval (s_resv ss) a with
            | None => SStop
            | Some r' =>
                match sym_readBI segs ss bc kx scr a n (amo_sx wd) with
                | None => SStop
                | Some (vold, scs, scr', nx') =>
                    SOk (SSR (p + 4) (if bv_eqb rd 0 then s_regs ss else sr_upd (s_regs ss) (ridx rd) vold)
                             (SE a n (amo_newvalB bc wd aop vold (g rs2)) :: s_log ss) (s_know ss) nx' r')
                        (scs ++ storeok_scB bc a n) scr'
                end
            end
          else SStop
      end
  | _ => SStop
  end.


Lemma sym_readBI_eqf : forall segs ss bc, sym_readBI segs ss bc (mk_kix (s_know ss)) = sym_readB segs ss bc.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "SP0!1+^A+dN!2+_2+P0!2+_21+hL!2+_22+Y!1+^J3%sx';R+24%n;R+Y5%rb;R+P%rk;R+S%n;R+Y%sx;R+2%hints;R!1+^A+2%acc;R0+d\!1'hO#6!1,^B+dN!8'hQ#6!1'hR#7!1'aU#4!1'aV#4#3#2!1'hS#59!1+^A+dN!1+^A+2!3'hU#9#7#6!1'hW#8!1'hX#8!1'hY#:!2,^S3!4,_:2+Y!4,_:1+hL!4,_:+P0!2'hT#9#3!3'a9+dN=#2!3,hV>?#1@!1'aU#6!1'aV#6!2,^S3!4,_:2+Y!4,_:1+hL!4,_:+P0!2'hT#;#3!3'a9+dN!3'hU#;#9#8#2!3,hV!1'hW#:!1'hX#:#1!1'hY#<!1'hX#9!1'hY#;-^ARN$x;R!1+^A+P+PE2!1,ZF$e;R+P$l;R!1+^A+P#2!3'hU#:#8#7!1'hW#9!1+^A+P!1,^B+P!2,^S3!4,_:2+Y!4,_:1+hL!4,_:+P0G!3'a9+dNH!3,^F+dN!4,hZ#8#7#6G#2!3,hVI-^ARN$x;R!1+^A+PJE2K$e;R+P$t;R!1+^A+P#1#1!1,^HF!1,^Z3-^ARN$x;R!1+^A+P+P?2!1,Z@$e;R+P$l;R!1+^A+P#2!1'hN8$segs;R!1+^A+d[$ss;R+hK$bc;R+_L!5'_\+hL%a;R+_46!4'hM#3#2#1!1'hN!1'hO#2!3'hP#3#2#1$x;R+hL!5'_\+_46!5'hM#4#3#2!1'hN!1'hO#3#1!4'hP#4#3#2#1$x0;R+_4!5'_\+Y5!6'hM#5#4#3!1'hN!1'hO#4#2#1!5'hP#5#4#3#2#1$x1;R+Y!5'_\+24!7'hM#6#5#4!1'hN!1'hO#5#3#2#1!6'hP#6#5#4#3#2#1$x2;R+2vd!6'X7!3'hI#5#78$l;R7!3+14-d\RN$x;R+d\4:3$v;R+P$scs;R;$hints;R<A$scs;R;$hints;R<-d\RN$x;R+d\4!6#3BC#5#4#1#23$v;R+P$scs';R;$hints';R<D$scs';R;$hints';R<LMM-d\RN$x;R+d\4:3$v;R+P$scs;R;$hints;R<A$scs;R;$hints;R<-d\RN$x;R+d\4!9'hI#8#:!1'hO#9BC#5#4#1#23$v;R+P$scs';R;$hints';R<D$scs';R;$hints';R<LMM!2,64-d\RN$x;R+d\4!8'hQ#5!1'hR#6!1'aU#3!1'aV#3#2#1!1'hS#493$v;R+P$scs;R;$hints;R<!2,^S3!4,_:2+Y!4,_:1+hL!4,_:+P0!2'hT#8#3!3'a9+dN!3'hU#8#6#5#2!3,hV!1'hW#7!1'hX#7#1!1'hY#9$scs;R;$hints;R<-d\RN$x;R+d\4!9'hI#7#9!1'hO#8!1'aU#5!1'aV#5#4#3#1#23$v;R+P$scs';R;$hints';R<!2,^S3!4,_:2+Y!4,_:1+hL!4,_:+P0!2'hT#:#3!3'a9+dNH#2!3,hVIE#1F$scs';R;$hints';R<!2,^S3!4,_:2+Y!4,_:1+hL!4,_:+P0N!3'a9+dN=!3,^F+dN!4,hZ#7#6#5N#2!3,hV>-^ARN$x;R!1+^A+PJ?2K$e;R+P$t;R!1+^A+P#1#1!1,^H@MM!4'h[#5O#78!3'h\#58#7!3+14!8'hM#7#6#5O#4#3#2#1!7'hP#7#6#5#4#3#2#1").
Qed.
