Definition kentry_overlayB (bc : bctx) (rb : expr) (rk : Z) (n : nat) (K : kentry) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 5 "S20-_4RN$a;R+_4+2#21$kb;R+P$kk;R+S!7'm=#9#8#7#6#2#1#3-_4RN$a;R+_4+2#31$kb;R+P$kk;R+S!7'm=#:#9#8#7#2#1#4$bc;R+_L$rb;R+P$rk;R+S$n;R+Y$K;R+^K-^KRN$K;R+^K+2#1:$a;R+_4$w;R+Y$v;R+P,7$a;R+_4$len;R+P0$a;R+_4$len;R+P$k;R+Y1$lo;R+S$hi;R+S,7$e;R+P$m;R+S,7$e;R+P$lo;R+S$hi;R+S,7$a;R+_4$n0;R+P,7$a1;R+_4$n1;R+P$a2;R+_4$n2;R+P,7$a;R+_4$len;R+P$c;R+S1$a;R+_4$len;R+P0").

Definition kwr_offimageB (bc : bctx) (kb : expr) (kk : Z) (len : expr) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S20!2+_2+S+S|10;$bc;R+_L$kb;R+P$kk;R+S$len;R+P-^JRN$x;R!1+^J0+2!2'`I#4#32$p;R0-_2RN$p;R!2+_2+S+S+2#11$blo;R+S$bhi;R+S-PRN$len;R+P+2#48$l0;R+S!3'm>/segs;!2'_@#3#6!2'_@!2'_@#2#6!2'_O#1!2'_>!1,_?1!1,_?|600;$n;R+Y,7$op;R+0$a;R+P$b;R+P,7$op;R+0$a;R+P$b;R+P,7$op;R+F$a;R+P$b;R+P,7$op;R+F$a;R+P$b;R+P,7$sx;R+2$lo;R+Y$n;R+Y$e;R+P,7$sx;R+2$k;R+Y$i;R+S$n;R+Y,7,7").
Definition kentry_readableB (bc : bctx) (rb : expr) (rk : Z) (n : nat) (K : kentry) : bool :=
  match K with
  | KWord (SA kb kk) w _ =>
      match rel_lit rb rk (Z.of_nat n) kb kk (Z.of_nat w) with RInside _ => true | _ => false end
  | KWr (SA kb kk) len => zf_coversB bc rb rk n kb kk len && kwr_offimageB bc kb kk len   (* [comment removed for export] *)
  | _ => kentry_overlayB bc rb rk n K
  end.

Definition kn_readableB (bc : bctx) (kn : list kentry) (rb : expr) (rk : Z) (n : nat) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 5 "S00$bc;R+_L$kn;R!1+^A+^K$rb;R+P$rk;R+S$n;R+Y!2'`A!3'm?+^K!4'm@#5#3#2#1#4!6'mA/segs;,4#4#3#2#1").

Definition kn_overlayB (bc : bctx) (kn : list kentry) (rb : expr) (rk : Z) (n : nat) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 5 "S00$bc;R+_L$kn;R!1+^A+^K$rb;R+P$rk;R+S$n;R+Y!2'`A!3'm?+^K!4'mB#5#3#2#1#4!6'mA/segs;,7#4#3#2#1").

Definition x_dischargeableB (bc : bctx) (ss ss' : sym_state) (rb : option (saddr * nat * bool)) (sc : sidecond) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 5 "S60!2+_2+_4+Y!2+_20+2}1}8!1'hY#:!1'aU#5$bc;R+_L$ss;R+hK$ss';R+hK$rb;R!1+^J1$sc;R+dN&kn;R!1'hO#4!1+^A+^K-dNRN$sc;R+dN+2#27$taken;R+2$c;R+d@$a;R+P$b;R+P,7$a;R+_4$n;R+P-PRN$n;R+P+2#18$z;R+S!2'^6!2'^6!2'_;!1,_?,`;#1!2'_;#1!1,_?|30;!6'mC/segs;!1'aR#9#4!1'aU#3!1'aV#3!1'fT#1$n0;R+Y,7$op;R+0$a0;R+P$b;R+P,7$op;R+0$a0;R+P$b;R+P,7$op;R+F$a0;R+P$b;R+P,7$op;R+F$a0;R+P$b;R+P,7$sx;R+2$lo;R+Y$n0;R+Y$e;R+P,7$sx;R+2$k;R+Y$i;R+S$n0;R+Y,7$a1;R+_4$n1;R+P$a2;R+_4$n2;R+P,7$a1;R+_4$n1;R+P$a2;R+_4$n2;R+P,7$a;R+_4$n;R+Y!2'^6!2'^6!2'`C2#1!2'`C#13!6'mD/segs;!1'aR#8#3!1'aU#2!1'aV#2#1$a;R+_4$n;R+Y$sx;R+2$e;R+P-PRN$e;R+P+2#18$z;R+S,7$j;R+Y!2'^6!2'^6!2'^6!2'^6!2'^6!2'^6-^JRN$rb;R!1+^J1+2#82$p;R1-_2RN$p;R!2+_20+2+2#11$p0;R0$sx';R+2-_2RN$p0;R!2+_2+_4+Y+2#21$a';R+_4$n';R+Y!2'^6!2'^6!2'iY#2#:!2'^4#1#9!2'^;#3#8,7!2'^4#14!2'mE#1!1'hY#9!2'mF45!2'`C2#4!2'`C#43!6'mC/segs;!1'aR#;#65!1'aV#5#4$op;R+0$a0;R+P$b;R+P,7$op;R+0$a0;R+P$b;R+P,7$op;R+F$a0;R+P$b;R+P,7$op;R+F$a0;R+P$b;R+P,7$sx0;R+2$lo;R+Y$n0;R+Y$e0;R+P,7$sx0;R+2$k;R+Y$i;R+S$n0;R+Y,7$a;R+P$b;R+P,7").

Definition x_filterB (bc : bctx) (ss ss' : sym_state) (scs : list sidecond) : list sidecond :=
  match scs with
  | [] => []          (* [comment removed for export] *)
  | _ => let rb := find_readbase (s_next ss) scs in
         List.filter (fun sc => negb (x_dischargeableB bc ss ss' rb sc)) scs
  end.

Definition sym_stepXB (bc : bctx) (K : nat) (i : instr) (ss : sym_state) (scr : scripts) : stepres :=
  match sym_stepB bc segs i ss scr with
  | SOk ss' scs scr' =>
      if Nat.leb (s_next ss) (s_next ss')            (* [comment removed for export] *)
      then SOk (cap_rd K i ss') (x_filterB bc ss ss' scs) scr'
      else SStop
  | SStop => SStop
  end.


Lemma zf_coversB_eqf : forall fk, zf_coversB (mkbc fk) = zf_covers fk.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S:0%len;R+P+2%kk;R+S0%kb;R+P1%n;R+Y2%b1;R+P%k1;R+S%n1;R+P%b2;R+P%k2;R+S%n2;R+P+2|10;!2'_O#1!2'_>!1,_?5!1,_?|600;-PRN$len;R+P+2#28$l0;R+S-fIRN$x;R+fI+2!6'fO#8#7!1'`B#6#5#464$delta;R+S,4,7,7,7$n0;R+Y,7$op;R+0$a;R+P$b;R+P,7$op;R+0$a;R+P$b;R+P,7$op;R+F$a;R+P$b;R+P,7$op;R+F$a;R+P$b;R+P,7$sx;R+2$lo;R+Y$n0;R+Y$e;R+P,7$sx;R+2$k;R+Y$i;R+S$n0;R+Y,7!1'dP#5!1'a?#7$fk;R!1+^A+^K!5'_\+P%rk;R+S3!1'm=!1'a?#1!1'mG#1$x;R+P!5'_\+S3!2'm=!1'a?#2#1!2'mG#2#1$x0;R+S!5'_\+Y2!3'm=!1'a?#3#2#1!3'mG#3#2#1$x1;R+Y!5'_\+P1!4'm=!1'a?#4#3#2#1!4'mG#4#3#2#1$x2;R+P!5'_\+S0!5'm=!1'a?#5#4#3#2#1!5'mG#5#4#3#2#1$x3;R+S!5'_\+P+2!6'm=!1'a?#6#5#4#3#2#1!6'mG#6#5#4#3#2#1$x4;R+Pvd!6'X4!1'c2#7$b;R4!3+1+2!2'`A7!6#1#7#68#4#3#2!2'`A7!7'c2#8#7#68#4#3#2!2,6+2!2'`A-PRN$len;R+P+2#18$l0;R+S-fIRN$x;R+fI+2!6'fO#7#6!1'`B#5#4#364$delta;R+S,4,7,7,7$n0;R+Y,7$op;R+0$a;R+P$b;R+P,7$op;R+0$a;R+P$b;R+P,7$op;R+F$a;R+P$b;R+P,7$op;R+F$a;R+P$b;R+P,7$sx;R+2$lo;R+Y$n0;R+Y$e;R+P,7$sx;R+2$k;R+Y$i;R+S$n0;R+Y,7!7'c2#7#6#5!1'dP#4#3#2#1!1'c19!1'c7#7!3+1+2!7'm=9#6#5#4#3#2#1!7'mG#7#6#5#4#3#2#1").
Qed.
