Lemma kentry_readableB_eqf : forall fk, kentry_readableB (mkbc fk) = kentry_readable segs fk.   Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "SE0%K;R+^K+2%n;R+Y0%rk;R+S1%kb;R+P%kk;R+S%len;R+P+2!1'`B#4-_4RN$a;R+_4+2#31$kb;R+P$kk;R+S-fIRN$x;R+fI+2!6'fO#:#9!1'`B#8#2#144$delta;R+S,4,7,7,7!5'mB!1'a?#8#7#6#5#4!5'mB!1'a?#9#8#7#6#5!1'a?#:!7'm=8#9#8#7#2#1#3!5'mH#8#7#6#5#4!5'mH#9#8#7#6#5!5'mK/segs;#:#2#1#3!5'mH#:#9#8#7#6-^KRN$K;R+^K+2#2:$a;R+_4$w;R+Y$v;R+P5$a;R+_4$n0;R+P:$a;R+_4$n0;R+P$k;R+Y;$lo;R+S$hi;R+S:$e;R+P$m;R+S:$e;R+P$lo;R+S$hi;R+S;$a;R+_4$len;R+P-_4RN$a;R+_4+2#21$kb;R+P$kk;R+S!2'^6!7'mG#:#9#8#7#2#1#3<$a1;R+_4$n1;R+P$a2;R+_4$n2;R+P=$a;R+_4$n0;R+P$c;R+S;$a;R+_4$n0;R+P:%rb;R+P2!4#3#7#6#5#4!4#4#8#7#6#5%rb;R+P%rk;R+S%n;R+Y3!5'mH#7#6#5#4#3!1'a?#5$fk;R!1+^A+^K!5'_\+P2!1'm@!1'a?#1!2'mL/segs;#1$x;R+P!5'_\+S1!2'm@!1'a?#2#1!3'mL/segs;#2#1$x0;R+S!5'_\+Y0!3'm@!1'a?#3#2#1!4'mL/segs;#3#2#1$x1;R+Y!5'_\+^K+2!4'm@!1'a?#4#3#2#1!5'mL/segs;#4#3#2#1$x2;R+^Kvd!6'X3!2'mK/segs;#5$b;R3!3+1+2-^KRN$K;R+^K+2#2:$a;R+_4$w;R+Y$v;R+P5$a;R+_4$n0;R+P6$a;R+_4$n0;R+P$k;R+Y7$lo;R+S$hi;R+S6$e;R+P$m;R+S6$e;R+P$lo;R+S$hi;R+S7$a;R+_4$len;R+P-_4RN$a;R+_4+2#21$kb;R+P$kk;R+S!2'^69!3#5#2#1#3$a1;R+_4$n1;R+P$a2;R+_4$n2;R+P!5'mB8#9#8#7#6$a;R+_4$n0;R+P$c;R+S7$a;R+_4$n0;R+P6>!6'X?!1'mH#5$b;R?!3+1+2-^KRN$K;R+^K+2#2:$a;R+_4$w;R+Y$v;R+P5$a;R+_4$n0;R+P@$a;R+_4$n0;R+P$k;R+YA$lo;R+S$hi;R+S@$e;R+P$m;R+S@$e;R+P$lo;R+S$hi;R+SA$a;R+_4$len;R+P-_4RN$a;R+_4+2#21$kb;R+P$kk;R+S!2'^69<$a1;R+_4$n1;R+P$a2;R+_4$n2;R+P!4#5#9#8#7#6$a;R+_4$n0;R+P$c;R+SA$a;R+_4$n0;R+P@>!6'XB!1'mG#5$b;RB!3+1+2-^KRN$K;R+^K+2#2:$a;R+_4$w;R+Y$v;R+P5$a;R+_4$n0;R+P:$a;R+_4$n0;R+P$k;R+Y;$lo;R+S$hi;R+S:$e;R+P$m;R+S:$e;R+P$lo;R+S$hi;R+S;$a;R+_4$len;R+P-_4RN$a;R+_4+2#21$kb;R+P$kk;R+S!2'^6!6#5#9#8#7#2#1#3<$a1;R+_4$n1;R+P$a2;R+_4$n2;R+P=$a;R+_4$n0;R+P$c;R+S;$a;R+_4$n0;R+P:>!2,6+2-^KRN$K;R+^K+2#1:$a;R+_4$w;R+Y$v;R+P-_4RN$a;R+_4+2#31$kb;R+P$kk;R+S-fIRN$x;R+fI+2!6'fO#9#8!1'`B#7#2#144$delta;R+S,4,7,7,7$a;R+_4$n0;R+PC$a;R+_4$n0;R+P$k;R+Y:$lo;R+S$hi;R+SC$e;R+P$m;R+SC$e;R+P$lo;R+S