Lemma sym_execTX_know : forall t K fuel first stops ss,
  s_know (sym_execTX segs t K fuel first stops ss) = s_know ss.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S40!1+^A+^K!1'n6#1!1'hO1!1'hO#1$t;R'n4$K;R+Y$fuel;R+Y$first;R+2$stops;R!1+^A+S$ss;R+hKvd!6'X02$l;R0!3+10#1!1'hO#2-hKRN$s;R+hK!3+1023#11$s_pc;R+S$s_regs;R!1+^A+P$s_log;R!1+^A+iO$s_know;R!1+^A+^K$s_next;R+Y$s_resv;R!1+^J+_4!6$s_pc0;R+S$s_regs0;R!1+^A+P$s_log0;R!1+^A+iO$s_know0;R0$s_next0;R+Y$s_resv0;R!1+^J+_4!2,60!1'hO!6,iH#6#5#4#3#2#1#6#5#4#3#2#1!1'hO!8'n7/segs;#6#5#4#3#211!8'n@#6#5#4#3#211!2,602!3+10!1'hO!7'n>/segs;#6#5#4#3#2#13").
Qed.
(* [comment removed for export] *)
Definition sym_stepXBI (bc : bctx) (kx : kix) (K : nat) (i : instr) (ss : sym_state) (scr : scripts) : stepres :=
  match sym_stepBI bc kx segs i ss scr with
  | SOk ss' scs scr' =>
      if Nat.leb (s_next ss) (s_next ss')
      then SOk (cap_rd K i ss') (x_filterB bc ss ss' scs) scr'
      else SStop
  | SStop => SStop
  end.
Lemma sym_stepXBI_eq : forall K i ss scr,
  sym_stepXBI (mkbc (facts_of (s_know ss))) (mk_kix (s_know ss)) K i ss scr = sym_stepX segs K i ss scr.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S70!1'hO#2!1'a?!1'_[0!5'j;1/segs;#3#2#1!1+^A+dN!1'hY#3!5'n1/segs;#4#3#2#1!1'hN0$K;R+Y$i;R+i0$ss;R+hK$scr;R+hLvd!6'X+i12$s;R+i1!3+1+i1-i1RN$x;R+i1+i1#12$ss';R+hK$scs;R3$scr';R+hL-2RN$~R+2+i1!2'`C!1'hY#642!3,i4!3'mZ#8#7#3!4'mV!1'a?!1'_[!1'hO#6#6#3#2#1,i@,i@!5'n1/segs;#5#4#3#2vd!4'n<#4#3#2#1!3+1+i1-i1RN$x;R+i1+i122$ss';R+hK$scs;R3$scr';R+hL-2RN$~R+2+i1!2'`C!1'hY#542!3,i4!3'mZ#7#6#3!4'mV!1'a?!1'_[!1'hO#5#5#3#2#1,i@,i@5!6'nA16/segs;#3#2#1!5'nB1/segs;#3#2#1!3+1+i1!6'nC16#4#3#2#15").
Qed.
Fixpoint sym_execTXBI_go (bc : bctx) (kx : kix) (t : itab) (K : nat) (fuel : nat) (first : bool) (stops : list Z) (ss : sym_state) (ck : sym_state)
  : sym_state :=
  match fuel with
  | O => if s_clean ss then ss else ck
  | S f =>
      if (negb first && existsb (Z.eqb (s_pc ss)) stops)%bool then (if s_clean ss then ss else ck) else
      match itab_lookup t (s_pc ss) with
      | None => if s_clean ss then ss else ck
      | Some i =>
          match sym_stepXBI bc kx K i ss scr_nil with
          | SOk ss' [] _ => sym_execTXBI_go bc kx t K f false stops ss' (if s_clean ss' then ss' else ck)
          | _ => if s_clean ss then ss else ck
          end
      end
  end.
Definition sym_execTXBI (bc : bctx) (kx : kix) (t : itab) (K : nat) (fuel : nat) (first : bool) (stops : list Z) (ss : sym_state) : sym_state := ltac2:(Rpl.RP.run_i (rplG ()) 8 "S10!1'n6#1$bc;R+_L$kx;R+nD$t;R'n4$K;R+Y$fuel;R+Y$first;R+2$stops;R!1+^A+S$ss;R+hK!9'nE#8#7#6#5#4#3#200").
Lemma sym_execTXBI_go_eq : forall t K fuel first stops ss ck,
  sym_execTXBI_go (mkbc (facts_of (s_know ss))) (mk_kix (s_know ss)) t K fuel first stops ss ck = sym_execTX_go segs t K fuel first stops ss ck.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "SW0!1+^A+S!1'hO#2!1'a?!1'_[1!1'hN1%first;R+2%stops;R0%ss;R+hK%ck;R+hK!3+1+hK!9'nE23#8#7#5#4#3#2#1!8'n7/segs;#8#7#5#4#3#2#1-2RN$~R+2+hK!1'n8#42#4#3!2'n9#;!1'i:#4!1'hO#5!1+^A+dN!1'hO#8!1'n8#3-2RN$~R+2+hK:2#3#7-2RN$~R+2+hK!1'n8#:2#:#9!1'n8#5-2RN$~R+2+hK=2#5#4!1'hO#6!6'nC!1'a?!1'_[?!1'hN?#<#1#6'n:!1'hO#9-2RN$~R+2+hK:2#3#8-2RN$~R+2+hK!1'n8#;2#;#:!1'n8#6-2RN$~R+2+hKD2#6#5!5'n1/segs;#<#1#6'n:!1'hO#:-2RN$~R+2+hK:2#3#9-2RN$~R+2+hK!1'n8#<2#<#;-2RN$~R+2+hK!1'n8#72#7#6!5'n1/segs;#=#2#7'n:!1'hO#=-2RN$~R+2+hK:2#3#<-2RN$~R+2+hK!1'n8#?2#?#>!1+^A+dN!1'hO#A-2RN$~R+2+hKD2#6#@-2RN$~R+2+hK!1'n8#C2#C#B!8'n7/segs;#H#G#E,7#B#6Q!1,^B+dN!1+^A+^K!1,^H#6$t;R'n4$K;R+Y$fuel;R+Y!4'^E$fuel;R+Y4$first;R+2$stops;R0$ss;R+hK$ck;R+hK!2,6+hK!8'n7/segs;#7#6,^G#4#3#2#1$f;R+Y$IH;R4$first;R+2$stops;R0$ss;R+hK$ck;R+hKvd&b;R!2'^6!1'cJ#4!3'm?+S!1'U!1'i:#2#3+2-2RN$b;R+2!3+1+hK-2RN$~R+2+hK#125-^JRN$x;R!1+^J+i0+hK62$i;R+i0-i1RN$x;R+i1+hK!6'nC!1'a?!1'_[7!1'hN7#;#1#5'n:2$ss';R+hK$scs;R8$scr;R+hL-^ARN$scs;R!1+^A+dN+hK#22!9'nE!1'a?!1'_[9!1'hN9#?#>#<,7#9#3;$s;R+dN$l;R!1+^A+dN<>5-2RN$~R+2+hK#125-^JRN$x;R!1+^J+i0+hK62$i;R+i0-i1RN$x;R+i1+hK!5'n1/segs;#;#1#5'n:2$ss';R+hK$scs;R8$scr;R+hL-^ARN$scs;R!1+^A+dN+hK#22!8'n7/segs;#?#>#<,7#9#3;$s;R+dN$l;R!1+^A+dN<>5#12!2,6+hK-2RN$~R+2+hK:2#3#2&o;R!2'n9#:!1'i:#3!1+^J+i0-^JRN$o;R!1+^J+i0!3+1+hK-^JRN$x;R!1+^J+i0+hK#12$i;R+i0-i1RN$x;R+i1+hK@2$ss';R+hK$scs;R8$scr;R+hL-^ARN$scs;R!1+^A+dN+hK#22!9'nE!1'a?!1'_[A!1'hNA#@#?#=,7#:#3B$s;R+dN$l;R!1+^A+dNCE>-^JRN$x;R!1+^J+i0+hK#12$i;R+i0-i1RN$x;R+i1+hKF2$ss';R+hK$scs;R8$scr;R+hL-^ARN$scs;R!1+^A+dN+hK#22!8'n7/segs;#@#?#=,7#:#3B$s;R+dN$l;R!1+^A+dNCE>#12$i;R+i0!1$i;R+i0!6'X+i1F$s;R+i1!3+1+hK-i1RN$x;R+i1+hK#12$ss';R+hK$scs;R8$scr;R+hL-^ARN$scs;R!1+^A+dN+hK#22!9'nE!1'a?!1'_[G!1'hNG#A#@#>,7#;#3H$s;R+dN$l;R!1+^A+dNIJ-i1RN$x;R+i1+hKK2$ss';R+hK$scs;R8$scr;R+hL-^ARN$scs;R!1+^A+dN+hK#22!8'n7/segs;#A#@#>,7#;#3H$s;R+dN$l;R!1+^A+dNIJ&s;RF+i1&E;R!2,6+i1#1!3+1+i1K#1!1-i1RN$s;R+i1%E;R!3+1+i1!5'n1/segs;#?#4#9'n:#1!3+1+hK-i1RN$x;R+i1+hK#22$ss';R+hK$scs;R8$scr;R+hL-^ARN$scs;R!1+^A+dN+hK#22!9'nE!1'a?!1'_[L!1'hNL#D#C#A,7#>#3M$s;R+dN$l;R!1+^A+dNN<-i1RN$x;R+i1+hK#22$ss';R+hK$scs;R8$scr;R+hL-^ARN$scs;R!1+^A+dN+hK#22!8'n7/segs;#D#C#A,7#>#3M$s;R+dN$l;R!1+^A+dNN<#22$ss;R+hK$scs;R8$scr;R+hL!3$ss';R+hK$scs;RO$scr';R+hL$E;R!3+1+i1!5'n1/segs;#D#9#>'n:!3,i4#3#2#1!1-^ARN$l;R!1+^A+dN%E;R!3+1+i1!5'n1/segs;#F#;#@'n:!3,i4#5#1#3!3+1+hK-^ARN$scs;R!1+^A+dN+hK#22!9'nE!1'a?!1'_[P!1'hNP#H#G#E,7#B#6Q$s;R+dN$l;R!1+^A+dNR-^ARN$scs;R!1+^A+dN+hK#22S$s;R+dN$l;R!1+^A+dNR#32$E;R!3+1+i1!5'n1/segs;#E#:#?'n:!3,i4#4T#2!6'8U7$l;RU!3+1+hK!9'nE!1'a?!1'_[#1!1'hN#1#H#G#E,7#B#6QS!4#C,7#A#5-2RN$~R+2+hK=2#5#?!1'hO#@!8'n;#F#;#@'n:#5T#3#1$s;R+dN$l;R!1+^A+dN!2$s;R+dN$scs;RO$E;R!3+1+i1!5'n1/segs;#I#>#C'n:!3,i4#8!3,^F+dN#2#1#6!2,6+hK-2RN$~R+2+hK!1'n8#D2#D#C#2#1#1#3#2#1$E;R!3+1+i1!5'n1/segs;#>#3#8'n:,i@!2,6+hK-2RN$~R+2+hK!1'n8#92#9#8#1@!4'nF#<#1#6'n:#1!2,6+hK5!3+1+hK!9'nE23#9#8V#4#3#2#1!8'n7/segs;#9#8V#4#3#2#1#1").
Qed.
Lemma sym_execTXBI_eq : forall kn0 t K fuel first stops ss,
  s_know ss = kn0 ->
  sym_execTXBI (mkbc (facts_of kn0)) (mk_kix kn0) t K fuel first stops ss = sym_execTX segs t K fuel first stops ss.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S70!1+^A+^K!1'hO#1!1'hO#2!1'a?!1'_[#1!1'hN#1!1'n6#3!1'n6#4$kn0;R0$t;R'n4$K;R+Y$fuel;R+Y$first;R+2$stops;R!1+^A+S$ss;R+hK$H;R!3+101#7!6'802$kn0;R0!3+1+hK!8'nG34#8#7#6#5#4#3!7'n>/segs;#8#7#6#5#4#3vd&H;R-hKRN$s;R+hK!3+10!1'hO!1'n6#11#21$s_pc;R+S$s_regs;R!1+^A+P$s_log;R!1+^A+iO$s_know;R!1+^A+^K$s_next;R+Y$s_resv;R!1+^J+_4!6$s_pc0;R+S$s_regs0;R!1+^A+P$s_log0;R!1+^A+iO$s_know0;R0$s_next0;R+Y$s_resv0;R!1+^J+_4!2,60!1'hO!6,iH#6#5#4#3#2#1#6#5#4#3#2#1!3+10!1'hO!1'n6#22!6'80!1'hO5$l;R0!3+1+hK!9'nE34#9#8#7#6#566!8'n7/segs;#9#8#7#6#566!7'nH#8#7#6#5#455!1'hO#3#1!3+1+hK!8'nG!1'a?!1'_[2!1'hN2#7#6#5#4#3#2!7'n>/segs;#7#6#5#4#3#2#8#1").
Qed.

End WithSegs.

(* [comment removed for export] *)
Definition kcutB (bc : bctx) (mk : saddr -> expr -> kentry) (wb : expr) (wk : Z) (wn : expr)
           (kb : expr) (kk : Z) (len : expr) : list kentry :=
  let ws := mkAlu ALU_ADD wb (ELit wk) in
  let ks := mkAlu ALU_ADD kb (ELit kk) in
  (* [comment removed for export] *)
  let low :=
    if (if lin_ge0B bc [(kb, kk)] [(wb, wk)] then false   (* [comment removed for export] *)
        else if lin_ge0B bc [(wb, wk)] [(kb, kk)] then lin_ge0B bc [(kb, kk); (len, 0%Z)] [(wb, wk)] else false)
    then [mk (SA kb kk) (mkAlu ALU_SUB ws ks)] else [] in
  let high :=
    if (if lin_ge0B bc [(kb, kk); (len, 0%Z)] [(wb, wk); (wn, 0%Z)]            (* [comment removed for export] *)
        then if lin_ge0B bc [(wb, wk); (wn, 0%Z)] [(kb, kk)]                    (* [comment removed for export] *)
             then lin_ge0B bc [(ELit 0, (two64 - 1)%Z)] [(kb, kk); (len, 0%Z)]  (* [comment removed for export] *)
             else false
        else false)
    then let we := mkAlu ALU_ADD ws wn in
         let '(hb, ho) := split_lit we in
         let ha := if (lin_ge0B bc [(hb, ho)] [(wb, wk); (wn, 0%Z)] && lin_ge0B bc [(wb, wk); (wn, 0%Z)] [(hb, ho)])%bool
                   then SA hb ho else SA we 0%Z in
         [mk ha (mkAlu ALU_SUB (mkAlu ALU_ADD ks len) we)]
    else [] in
  low ++ high.

Definition kzero_cutB (bc : bctx) (wb : expr) (wk : Z) (wn : expr)
           (kb : expr) (kk : Z) (len : expr) : list kentry := ltac2:(Rpl.RP.run_i (rplG ()) 7 "S00$bc;R+_L$wb;R+P$wk;R+S$wn;R+P$kb;R+P$kk;R+S$len;R+P!8'nI#7,_6#6#5#4#3#2#1").

Definition kfill_cutB (bc : bctx) (c : Z) (wb : expr) (wk : Z) (wn : expr)
           (kb : expr) (kk : Z) (len : expr) : list kentry := ltac2:(Rpl.RP.run_i (rplG ()) 8 "S00$bc;R+_L$c;R+S$wb;R+P$wk;R+S$wn;R+P$kb;R+P$kk;R+S$len;R+P!8'nI#8$a;R+_4$n;R+P!3,_G#2#1#9#6#5#4#3#2#1").

Definition kunk_cutB (bc : bctx) (wb : expr) (wk : Z) (wn : expr)
           (kb : expr) (kk : Z) (len : expr) : list kentry := ltac2:(Rpl.RP.run_i (rplG ()) 7 "S00$bc;R+_L$wb;R+P$wk;R+S$wn;R+P$kb;R+P$kk;R+S$len;R+P!8'nI#7,_H#6#5#4#3#2#1").

Definition prune_zfB (bc : bctx) (mk : saddr -> expr -> kentry) (wb : expr) (k : Z) (w : nat)
           (K : kentry) (kb : expr) (kk : Z) (len : expr) (apart : unit -> bool) (hints : list bool)
           (diffbase : unit -> list kentry * list sidecond * list bool)
  : list kentry * list sidecond * list bool :=
  (* [comment removed for export] *)
  if expr_eqb kb wb then
    match len with
    | ELit l0 => (ktrim mk kb kk l0 k w, [], hints)
    | _ => if Z.leb (k + Z.of_nat w) kk then ([K], [], hints)
           else (kcutB bc mk wb k (elen w) kb kk len, [], hints)
    end
  else if apart tt then ([K], [], hints)
  else match kcutB bc mk wb k (elen w) kb kk len with
       | [] => diffbase tt
       | cut => (cut, [], hints)
       end.

Definition prune1pB (bc : bctx) (sp : sprep) (wa : saddr) (w : nat) (wv : expr) (K : kentry) (hints : list bool)
  : list kentry * list sidecond * list bool :=
  let k := a_off wa in
  let diffbase (ka : saddr) (kl : expr) :=
    let apart := ranges_apart_pB bc sp (a_base wa) k (elen w) (a_base ka) (a_off ka) kl in
    if apart then ([K], [], hints) else
    match hints with
    | true :: hs => ([K], [SCDisj wa (elen w) ka kl], hs)   (* [comment removed for export] *)
    | false :: hs => ([], [], hs)                          (* [comment removed for export] *)
    | [] => ([], [], [])                                   (* [comment removed for export] *)
    end in
  match K with
  | KAlign _ _ => ([K], [], hints)
  | KRange _ _ _ => ([K], [], hints)
  | KWr _ _ => ([K], [], hints)
  | KDisj _ _ _ _ => ([K], [], hints)
  | KImg lo hi =>
      match a_base wa with
      | ELit 0 =>
          let r1 := if Z.ltb lo (Z.min k hi) then [KImg lo (Z.min k hi)] else [] in
          let lo2 := Z.max lo (k + Z.of_nat w) in
          let r2 := if Z.ltb lo2 hi then [KImg lo2 hi] else [] in
          (r1 ++ r2, [], hints)
      | _ => if Z.ltb (hi - lo) (2 ^ 64) then diffbase (SA (ELit 0) lo) (ELit (hi - lo))
             else ([], [], hints)
      end
  | KZero (SA kb kk) len =>
      prune_zfB bc KZero (a_base wa) k w K kb kk len
               (fun _ => ranges_apart_pB bc sp (a_base wa) k (elen w) kb kk len) hints (fun _ => diffbase (SA kb kk) len)
  | KFill (SA kb kk) len c =>
      prune_zfB bc (fun a n => KFill a n c) (a_base wa) k w K kb kk len
               (fun _ => ranges_apart_pB bc sp (a_base wa) k (elen w) kb kk len) hints (fun _ => diffbase (SA kb kk) len)
  | KUnk (SA kb kk) len =>
      prune_zfB bc KUnk (a_base wa) k w K kb kk len
               (fun _ => ranges_apart_pB bc sp (a_base wa) k (elen w) kb kk len) hints (fun _ => diffbase (SA kb kk) len)
  | KWord (SA kb kk) w' v =>
      if expr_eqb kb (a_base wa) then
        (if (Z.leb (kk + Z.of_nat w') k || Z.leb (k + Z.of_nat w) kk)%bool
         then ([K], [], hints) else (kword_cut kb kk w' v k w, [], hints))   (* [comment removed for export] *)
      else if ranges_apart_pB bc sp (a_base wa) k (elen w) kb kk (elen w') then ([K], [], hints)
      else if (Nat.eqb w 1 && Nat.eqb w' 1 && expr_eqb wv v)%bool
      then ([K], [], hints)   (* [comment removed for export] *)
      else diffbase (SA kb kk) (elen w')
  | KBlob (SA kb kk) len bk =>
      if expr_eqb kb (a_base wa) then
        match len with
        | ELit l0 =>
            let l := (l0 mod 2 ^ 64)%Z in
            (if (Z.leb (kk + l) k || Z.leb (k + Z.of_nat w) kk)%bool
             then ([K], [], hints) else ([], [], hints))
        | _ => if Z.leb (k + Z.of_nat w) kk then ([K], [], hints) else ([], [], hints)
        end
      else diffbase (SA kb kk) len
  end.

Definition ranges_apart_pcB (bc : bctx) (sp : sprep) (b1 : expr) (k1 : Z) (n1 : expr)
           (br2 : option (Z * Z)) (b2 : expr) (k2 : Z) (n2 : expr) : bool :=
  match n1, n2 with
  | ELit z1, ELit z2 =>
      let m1 := zlit64 z1 in let m2 := zlit64 z2 in
      if (match sp_rng sp, br2 with
          | Some (lo1, hi1), Some (lo2, hi2) =>
              (Z.leb (hi1 + k1 + m1) (lo2 + k2) || Z.leb (hi2 + k2 + m2) (lo1 + k1))%bool
          | _, _ => false
          end) then true
      else if in_sidesB bc (sp_D sp) b2 k2 m2 then true
      else lin_apartB bc b1 k1 m1 b2 k2 m2
  | _, _ =>
    if (match sp_rng sp, br2, sp_h1 sp, xhiB bc n2 with
        | Some (lo1, hi1), Some (lo2, hi2), Some h1, Some h2 =>
            if (Z.leb (hi1 + k1 + h1) (lo2 + k2) || Z.leb (hi2 + k2 + h2) (lo1 + k1))%bool then true
            else (* [comment removed for export] *)
            if match end_hiB bc b1 k1 n1 lo1 hi1 h1 with Some e1 => Z.leb e1 (lo2 + k2) | None => false end then true
            else match end_hiB bc b2 k2 n2 lo2 hi2 h2 with Some e2 => Z.leb e2 (lo1 + k1) | None => false end
        | _, _, _, _ => false
        end) then true
    else if in_sides_xB bc (sp_Dx sp) b2 k2 n2 then true
    else if negb (shares_var b1 b2) then false
    else if lin_ge0B bc [(b2, k2)] [(b1, k1); (n1, 0%Z)] then true
    else lin_ge0B bc [(b1, k1)] [(b2, k2); (n2, 0%Z)]
  end.

Definition prune1pcB (bc : bctx) (sp : sprep) (wa : saddr) (w : nat) (wv : expr) (K : kentry) (hints : list bool)
  (br2 : option (Z * Z)) : list kentry * list sidecond * list bool := ltac2:(Rpl.RP.run_i (rplG ()) 8 "SL0!1+^A+2!1+^A+^K!1+^A+dN!2+_212!2+_230!1,^B+^K!1,^B+dN!4,_:1256!3,^F+^K#95!1'dP#;!1'aU#=!2'R#2:!7'nK#?#>#=#<#;#:#9!1'dP#<!1'dP#4!4,_:30!4,_:12!3,^F+^K#:56#9}1!2,dW#2#1!1'aU#<!2'R#2B!7'nK#>#=#<#;#:#9#8!9'nJ#>#=B#69#7#2#1#3!4,_:30!4,_:1286#8!2#5A#3!4,_:12!3,^F+^K#2#16!4,_:30H#:!2#6A#4!7'nK#<#;#:#9#8#7#6$bc;R+_L$sp;R+cV$wa;R+_4$w;R+Y$wv;R+P$K;R+^K$hints;R0$br2;R!1+^J!2+_2+S+S&k;R!1'aV#6+S&diffbase;R$ka;R+_4$kl;R+P&apart;R!9'nJ#;#:!1'aU#9#3!1'dP#8#4!1'aU#2!1'aV#2#1+2-2RN$apart;R+24#12!4,_:30!4,_:12!3,^F+^K#756#6-^ARN$hints;R!1+^A+24#62!4,_:307!1,^B+2$b;R+2$hs;R!1+^A+2-2RN$b;R+24#22!4,_:30!4,_:128!3,^F+dN!4,lS#<9#5#46#1!4,_:307#1%ka;R+_4%kl;R+P4-^KRN$K;R+^K4#5:$a;R+_4$w';R+Y$v;R+P-_4RN$a;R+_44#31$kb;R+P$kk;R+S-2RN$~R+24;2<-2RN$~R+24!9'nJ#?#>:#7=#8#2#1>2?-2RN$~R+24!2'^6!2'^6!2'^4#<@!2'^4#4@!2'R#;#32?!2#6A>$a;R+_4$len;R+P-_4RN$a;R+_44#21$kb;R+P$kk;R+S-2RN$~R+24C2D-2RN$~R+24E2F-^ARN$x;R!1+^A+^K4!7'nL#>B#69#2#1#32G$k0;R+^K$l;R!1+^A+^KI$a;R+_4$len;R+P$bk;R+Y-_4RN$a;R+_44#31$kb;R+P$kk;R+S-2RN$~R+24;2<J$lo;R+S$hi;R+SK$e;R+P$m;R+SK$e;R+P$lo;R+S$hi;R+S!7'nK#=#<#;#:#9#8#7$a;R+_4$n;R+PK$a1;R+_4$n1;R+P$a2;R+_4$n2;R+PD$a;R+_4$len;R+P$c;R+S-_4RN$a;R+_44#31$kb;R+P$kk;R+S-2RN$~R+24;2<-2RN$~R+24!9'nJ#?#>:#7=#8#2#1#42?-^ARN$x;R!1+^A+^K4!8'nM#?#3:#7=#2#1#42J$k0;R+^K$l;R!1+^A+^K!4,_:30H#;$a;R+_4$len;R+P-_4RN$a;R+_44#21$kb;R+P$kk;R+S-2RN$~R+24C2D-2RN$~R+24E2F-^ARN$x;R!1+^A+^K4!7'nN#>B#69#2#1#32G$k0;R+^K$l;R!1+^A+^KI").

Fixpoint prunepcB (bc : bctx) (sp : sprep) (wa : saddr) (w : nat) (wv : expr) (kn : list kentry) (hints : list bool)
  (cache : list (expr * option (Z * Z))) : list kentry * list sidecond * list bool :=
  match kn with
  | [] => ([], [], hints)
  | K :: rest =>
      let '(br2, cache') :=
        match kbase K with
        | Some kb => match br_lookup cache kb with
                     | Some r => (r, cache)
                     | None => let r := base_rangeB bc kb in (r, (kb, r) :: cache)
                     end
        | None => (None, cache)
        end in
      let '(kept, scs1, hs1) := prune1pcB bc sp wa w wv K hints br2 in
      let '(r, scs2, hs2) := prunepcB bc sp wa w wv rest hs1 cache' in
      (kept ++ r, scs1 ++ scs2, hs2)
  end.


