(* [comment removed for export] *)
Definition bkey (e : expr) : option nat := first_var e.
Record binfo := BI { bi_base : expr; bi_br : option (Z * Z) }.
Record ntab := NT { nt_vars : list (list (expr * positive)); nt_other : list (expr * positive); nt_next : positive; nt_info : ptree binfo }.
Definition nt_empty : ntab := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10!2+_2+P+e7!4,p7!1,^B!1+^A0!1,^B0,`;!1,h7+p8").
Fixpoint alookupE (l : list (expr * positive)) (b : expr) : option positive :=
  match l with
  | [] => None
  | (b', id) :: rest => if expr_eqb b b' then Some id else alookupE rest b
  end.
Definition nt_bucket (t : ntab) (k : option nat) : list (expr * positive) := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S10!2+_2+P+e7$t;R+p9$k;R!1+^J+Y-^JRN$k;R!1+^J+Y!1+^A0#12$n;R+Y!3'p:0!1'p;#3#1!1'p<#2").
Definition nt_add (t : ntab) (k : option nat) (p : expr * positive) (bi : binfo) : ntab := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S30!2+_2+P+e7!1'p>#5!1'p>#4$t;R+p9$k;R!1+^J+Y$p;R0$bi;R+p8-^JRN$k;R!1+^J+Y+p9#32$n;R+Y!4,p7!4'p=0!1'p;#5#1#3!1'p<#5!1'gN1!4'e<+p81#2!1'p?#5!4,p7!1'p;#4!3,^F0#2!1'p<#4!1'gN2!4'e<+p82#1!1'p?#4").
Definition intern (bc : bctx) (t : ntab) (b : expr) : positive * binfo * ntab := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S20!2+_2+e7+p8!2,pC#3!2'`N#5#3$bc;R+_L$t;R+p9$b;R+P&k;R!1'p@#1!1+^J+Y-^JRN$x;R!1+^J+e7!2+_20+p9!2'pA!2'pB#3#1#22$id;R+e7!4,_:0+p9!4,_:+e7+p8#1-^JRN$x;R!1+^J+p8+p8!3'e:+p8!1'p?#4#12$bi;R+p8#11#4&id;R!1'p>#3+e7&bi;R1+p8!4,_:0+p9!4,_:+e7+p8#2#1!4'pD#5#3!4,_:+P+e7#4#2#1").

Definition NTI (bc : bctx) (t : ntab) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S20!1+^J+Y!2+_2+P+e7$bc;R+_L$t;R+p9!2+^8%k;R0%b;R+P%id;R+e7%~R!3'pE1!4,_:+P+e7#2#1!2'pB#4#3!2+^8!3+10#4!1'p@#3!2+^8!3+1!1+^J+p8!3'e:+p8!1'p?#5#2!2,^S+p8!2,pC#3!2'`N#6#3!2'gJ#2!1'p>#5%k;R0%b;R+P%id;R+e7%id';R+e7%~R!3'pE1!4,_:+P+e7#3#2!2'pB#5#4%~R!3'pE1!4,_:+P+e7#4#2!2'pB#6#5!3+1+e7#4#3").

Lemma nt_bucket_empty : forall k, nt_bucket nt_empty k = [].
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S50!2+_2+P+e7!1+^A0!1,^B0!3+11-YRN$n;R+Y1#122$m;R+Y22!2,612$k;R!1+^J+Y-^JRN$o;R!1+^J+Y!3+11!2'pB'pF#12#12$n;R+Y!1$n;R+Yvdvd-YRN$n;R+Y3#124$n;R+Y!1$n;R+Y4#13!3+11!2'pB'pF!2,^S+Y#12#1vd4!3+11!2'pB'pF!1,^Z+Y2").
Qed.
Lemma NTI_empty : forall bc, NTI bc nt_empty.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S<0!1+^J+Y!2+_2+P+e7!3'pE1!4,_:+P+e7#2#1!2'pB'pF#3!1+^J+p8!1'p?'pF!1'p>'pF!4,_:+P+e7#3#2!2'pB'pF#4!3'pE167!3'pE1!4,_:+P+e7#4#2!2'pB'pF#5!1+^A1!1,^B1$bc;R+_L!4,h9%k;R0%b;R+P%id;R+e7%~R2!2+^8!3+10#4!1'p@#3!2+^8!3+13!3'e:+p84#2!2,^S+p8!2,pC#3!2'`N#5#3!2'gJ#25%k;R0%b;R+P%id;R+e7%id';R+e7%~R8%~R9!3+1+e7#4#3$k;R0$b;R+P$id;R+e7$~R2&H;R!6'8:7$l;R:!3'pE1!4,_:+P+e7#4#3#1#1;!1'pG#4!3'pE16;!2'<!2+^8!3+10#5!1'p@#4!2+^8!3+13!3'e:+p84#3!2,^S+p8!2,pC#4!2'`N#6#4!2'gJ#35#1$k;R0$b;R+P$id;R+e7$id';R+e7$~R8$~R9&H0;R!6'8:!2'pB'pF#6$l;R:!3'pE1!4,_:+P+e7#6#4#1#1;!1'pG#6!3'pE1!4,_:+P+e7#5#3;&H;R!6'8:!2'pB'pF#7$l;R:!3'pE1!4,_:+P+e7#7#6#1#3;!1'pG#7!3'pE1!4,_:+P+e7#6#5;!2'<!3+1+e7#6#5#2").
