Definition bnd_add (gs : gst) (gid bid : positive) (obr : option (Z * Z)) (lo hi : Z) : gst := ltac2:(Rpl.RP.run_i (rplG ()) 6 "S61lgrD;ge:d;!2+_2+S+S!1+^J0!1'rJ#6!2+_2+e71!2+_230!4,_:+e71#4#3$gs;R+rF$gid;R+e7$bid;R+e7$obr;R1$lo;R+S$hi;R+S!3,rC!1'rH#6!1'rI#6-^JRN$x;R!1+^J'rD'rK!3'e:'rD2#52$g;R'rD-_2RN$g;R!2+_230'rK#11$p;R3$p0;R0-_2RN$p;R!2+_2+e71'rK#21$b;R+e7$o;R1-_2RN$p0;R!2+_2+S+S'rK#31$l;R+S$h;R+S!4'e<4#<!4,_:305!4,_:+S+S!2'`?#2#9!2'_R#1#8!1'rJ#=!4'e<4#5!4,_:305!4,_:+S+S#2#12").
Fixpoint scan_entries (bc : bctx) (kn : list kentry) (t : ntab) (gs : gst) : list (option einfo) * ntab * gst :=
  match kn with
  | [] => ([], t, gs)
  | K :: rest =>
      match kdescr K with
      | Some (kb, kk, om) =>
          let '(r, t1) := intern bc t kb in
          let '(bid, bi) := r in
          let '(gid, gs1) := match om with
                             | Some m => let '(gid, gs0) := ggroup gs bid kk in (gid, bnd_add gs0 gid bid (bi_br bi) kk (kk + m)%Z)
                             | None => (xH, gs)
                             end in
          let '(infos, t2, gs2) := scan_entries bc rest t1 gs1 in
          (Some (EI bid gid kb (bi_br bi) kk om) :: infos, t2, gs2)
      | None =>
          let '(infos, t2, gs2) := scan_entries bc rest t gs in
          (None :: infos, t2, gs2)
      end
  end.

Definition sx_m1 (sx : stx) : Z := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$sx;R+q0!1'aZ!1'`B!1'q3#1").
(* [comment removed for export] *)
Definition verdict (sx : stx) (g : gval) : bool :=
  match g with
  | (b, obr, (glo, ghi)) =>
      if Pos.eqb b (sx_bid sx) then false else
      match sp_rng (sx_sp sx), obr with
      | Some (lo1, hi1), Some (lo2, hi2) =>
          (Z.leb (hi1 + a_off (sx_a sx) + sx_m1 sx - lo2) glo || Z.leb ghi (lo1 + a_off (sx_a sx) - hi2))%bool
      | _, _ => false
      end
  end.
(* [comment removed for export] *)
Fixpoint mk_fl (g : gval) (sxs : list stx) : list (stx * list stx) :=
  match sxs with
  | [] => []
  | sx :: rest => if verdict sx g then mk_fl g rest else (sx, rest) :: mk_fl g rest
  end.
Definition gfl : Type := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S02lgrD;c;<sc;!2+_2'rD!1+^A!2+_2+q0!1+^A+q0").
